    private void PrepareM1Output(NativeAgent a)
    {
        if(!enableM1){a.practiceActive=false;Array.Clear(a.m1Output,0,a.m1Output.Length);return;}int phase=Mathf.Max(0,Tick-m1ActivationTick)%5000;int block=Mathf.Max(0,Tick-m1ActivationTick)/5000;a.practiceActive=phase>=4750;if(a.practiceActive){if(a.practiceBlock!=block){a.practiceBlock=block;float angle=(float)(random.NextDouble()*Math.PI*2d);float magnitude=.35f+.65f*(float)random.NextDouble();a.practiceOutput[0]=Mathf.Cos(angle)*magnitude;a.practiceOutput[1]=Mathf.Sin(angle)*magnitude;float heading=(float)(random.NextDouble()*Math.PI*2d);a.practiceOutput[2]=Mathf.Sin(heading);a.practiceOutput[3]=Mathf.Cos(heading);}Array.Copy(a.practiceOutput,a.m1Output,4);}else a.m1Phenotype.Evaluate(a.globalInputs,a.m1Output);
    }

