        for(int i=0;i<NativeSpawnSlots;i++){GameObject lane=new GameObject("NativeTrainingLane_"+i);lane.transform.SetParent(trainingLaneRoot.transform);lane.transform.position=LaneCenter(i);var renderer=lane.AddComponent<SpriteRenderer>();renderer.sprite=BodyUtils.GetSquareSprite();renderer.color=new Color(.28f,.22f,.16f);lane.transform.localScale=new Vector3(TrainingLaneLength,TrainingLaneThickness,1f);BoxCollider2D collider=lane.AddComponent<BoxCollider2D>();collider.size=Vector2.one;collider.sharedMaterial=NativePhysicsMaterials.Ground;lane.AddComponent<GroundSurface>();}
    }
    private void EndTrainingArena(){if(trainingLaneRoot!=null)trainingLaneRoot.SetActive(false);if(ecosystemGround==null)ecosystemGround=GameObject.Find("Ground");if(ecosystemGround!=null)ecosystemGround.SetActive(true);}
    private static Vector2 LaneCenter(int slot)=>new Vector2((Mathf.Abs(slot)%NativeSpawnSlots-(NativeSpawnSlots-1)*.5f)*MinimumSpawnSeparation,WorldLayout.GroundTop);
    private static Vector2 LaneTangent(float degrees)=>new Vector2(Mathf.Cos(degrees*Mathf.Deg2Rad),Mathf.Sin(degrees*Mathf.Deg2Rad));
    private static Vector2 LaneNormal(float degrees)=>new Vector2(-Mathf.Sin(degrees*Mathf.Deg2Rad),Mathf.Cos(degrees*Mathf.Deg2Rad));
    private void StartCurriculumTrial(NativeAgent a)
    {
        EnsureTrainingArena();if(a.curriculum==null)a.curriculum=new NativeCurriculumState();if(a.curriculum.mode==NativeTrialMode.Settling)NativeSuccessCurriculum.StartNextTrial(a.curriculum);NativeDeterministicRng trialRandom=new NativeDeterministicRng(a.curriculum.randomState==0?(ulong)(7101+a.reservedSlot):a.curriculum.randomState);int stage=NativeSuccessCurriculum.TrialStage(a.curriculum,ref trialRandom);a.curriculum.randomState=trialRandom.State;float perturb=a.curriculum.IsPractice?(trialRandom.NextFloat()*2f-1f):0f;float slope=NativeSuccessCurriculum.SlopeDegrees(stage)+perturb;float distance=NativeSuccessCurriculum.Distance(stage)*(a.curriculum.IsPractice ? (.9f+trialRandom.NextFloat()*.2f) : 1f);int direction=NativeSuccessCurriculum.Direction(stage);float signedSlope=direction>0?slope:-slope;Vector2 tangent=LaneTangent(signedSlope),normal=LaneNormal(signedSlope),heading=tangent*direction;GameObject lane=trainingLaneRoot.transform.GetChild(a.reservedSlot).gameObject;lane.SetActive(true);lane.transform.position=LaneCenter(a.reservedSlot);lane.transform.rotation=Quaternion.Euler(0f,0f,signedSlope);a.lane=lane;a.trialStage=stage;a.trialDistance=distance;a.trialDirection=heading;a.trialNormal=normal;a.trialStart=LaneCenter(a.reservedSlot)-heading*3f+normal*(TrainingLaneThickness*.5f+BodyClearance(a,normal,signedSlope));a.trialGoal=a.trialStart+heading*distance;a.trialStartedTick=Tick;a.trialEpisode++;ResetTrialBody(a,a.trialStart,signedSlope);a.model.SetCurriculumGoal(a.trialGoal,heading,Tick+Mathf.RoundToInt(TrainingTimeoutSeconds/Time.fixedDeltaTime));Status="Curriculum "+NativeSuccessCurriculum.Label(stage)+" "+a.curriculum.mode;
    }
    private void ResetTrialBody(NativeAgent a,Vector2 torsoPosition,float torsoRotation)
    {
        if(a.resetPose==null||a.resetPose.Count==0)CaptureResetPose(a);foreach(NativeBodyResetPose pose in a.resetPose){if(pose.body==null)continue;pose.body.position=torsoPosition+(Vector2)(Quaternion.Euler(0f,0f,torsoRotation)*pose.localOffset);pose.body.rotation=torsoRotation+pose.rotationOffset;pose.body.linearVelocity=Vector2.zero;pose.body.angularVelocity=0f;pose.body.Sleep();}a.brain.ExpireActions();Physics2D.SyncTransforms();foreach(NativeBodyResetPose pose in a.resetPose)pose.body?.WakeUp();a.sequenceActive=false;a.observation=null;a.sequence=null;a.trialSettlingTicks=0;a.motionWindowTicks=a.movingEvidenceTicks=a.stillEvidenceTicks=0;a.isSustainedMoving=false;
    }
    private static void CaptureResetPose(NativeAgent a)
    {
        Rigidbody2D torso=a.identity.torso.Rigidbody;GameObject root=a.identity.transform.parent?.gameObject??a.identity.gameObject;foreach(Rigidbody2D body in root.GetComponentsInChildren<Rigidbody2D>(true))a.resetPose.Add(new NativeBodyResetPose{body=body,localOffset=Quaternion.Euler(0f,0f,-torso.rotation)*(body.position-torso.position),rotationOffset=Mathf.DeltaAngle(torso.rotation,body.rotation)});
    }
    private static float BodyClearance(NativeAgent a,Vector2 normal,float rotation)
    {
        float minimum=0f;foreach(NativeBodyResetPose pose in a.resetPose){if(pose.body==null)continue;float radius=0f;foreach(Collider2D collider in pose.body.GetComponents<Collider2D>())radius=Mathf.Max(radius,collider.bounds.extents.magnitude);Vector2 offset=Quaternion.Euler(0f,0f,rotation)*pose.localOffset;minimum=Mathf.Min(minimum,Vector2.Dot(offset,normal)-radius);}return -minimum+.08f;
